<section class="page-intro container-wide"><span class="eyebrow">ALMOST AT YOUR TABLE</span><h1>The final little details.</h1></section><section class="container-wide pb-5"><form action="<?= e(url('checkout')) ?>" method="post" class="checkout-grid"><?= csrf() ?><input type="hidden" name="checkout_key" value="<?= e($_SESSION['checkout_key']) ?>"><div class="panel"><?php require ROOT.'/app/Views/store/checkout-address.php'; ?><h3 class="mt-4">Payment method</h3><?php if(setting('cod_enabled')==='1'): ?><label class="payment-option"><input type="radio" name="payment_method" value="cod" required checked><span>Cash on delivery<small>Pay when your order arrives.</small></span></label><?php endif ?><?php if($onlinePaymentsEnabled): ?><label class="payment-option"><input type="radio" name="payment_method" value="razorpay" required><span>Pay online with Razorpay <?= setting('razorpay_mode')==='test'?'(test mode)':'' ?><small>UPI, cards and netbanking.</small></span></label><?php endif ?><?php if(!$onlinePaymentsEnabled && setting('cod_enabled')!=='1'): ?><p class="alert alert-warning">The store is not accepting payments yet. Please contact us.</p><?php endif ?></div><aside class="panel order-summary"><h2>Your flavour collection.</h2><?php foreach($totals['items'] as $i): ?><div class="summary-line small"><span><?= e($i['name']) ?><br><?= e($i['label']) ?> × <?= $i['quantity'] ?></span><strong><?= money($i['price']*$i['quantity']) ?></strong></div><?php endforeach ?><hr><?php require ROOT.'/app/Views/store/summary.php'; ?><button class="btn btn-primary w-100" <?= !$onlinePaymentsEnabled && setting('cod_enabled')!=='1'?'disabled':'' ?>>Place order →</button><p class="small muted mt-3">Review your details before ordering. By placing your order you accept our <a href="<?= e(url('page',['slug'=>'terms'])) ?>">terms</a>.</p></aside></form></section>
